require __DIR__.'/app/bootstrap.php';$userId=require_auth();$service=new NotificationService(db());
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');if($action==='all'){$service->markAllRead($userId);redirect('notifications.php');}if($action==='open'){$url=$service->markRead($userId,(int)($_POST['id']??0));redirect($url?:'notifications.php');}}
$items=$service->recent($userId,80);$title='Notifications';require __DIR__.'/partials/header.php';
?>
<section class="match-page"><div class="shell narrow-wide"><div class="section-head"><div><span class="eyebrow">Vacation Brain</span><h1>Notifications</h1><p class="muted">Matches, messages, reactions, discoveries, and other reasons to avoid doing actual work.</p></div><div class="today-actions"><a class="button secondary" href="<?=e(app_url('notification-settings.php'))?>">Notification settings</a><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><button class="button secondary" name="action" value="all">Mark all read</button></form></div></div>
<?php if(!$items):?><article class="match-empty"><h2>Nothing new.</h2><p>Your Vacation Brain is unusually peaceful.</p></article><?php else:?><div class="notification-list"><?php foreach($items as $n):?><form method="post" class="notification-row<?=empty($n['read_at'])?' unread':''?>"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$n['id']?>"><button name="action" value="open"><span class="notification-icon">◒</span><span><strong><?=e($n['title'])?></strong><?php if($n['body']):?><p><?=e($n['body'])?></p><?php endif;?><small><?=e(date('M j · g:i A',strtotime($n['created_at'])))?></small></span></button></form><?php endforeach;?></div><?php endif;?></div></section>
